function findContestMatch(n) {
  let teams = [];
  for (let i = 1; i <= n; i++) {
    teams.push(String(i));
  }
  while (teams.length > 1) {
    const next = [];
    for (let i = 0; i < teams.length / 2; i++) {
      next.push(`(${teams[i]},${teams[teams.length - 1 - i]})`);
    }
    teams = next;
  }
  return teams[0];
}

