function findContestMatch(n) {
  // Work out the left-to-right order of the teams in the final string by doubling the bracket:
  // in a bracket of size 2m, each team t of the size-m bracket meets 2m + 1 - t in the first round.
  let order = [1];
  while (order.length < n) {
    const size = order.length * 2;
    order = order.flatMap(team => [team, size + 1 - team]);
  }
  const build = (low, high) => {
    if (high - low === 1) return String(order[low]);
    const middle = (low + high) / 2;
    return '(' + build(low, middle) + ',' + build(middle, high) + ')';
  };
  return build(0, n);
}

